python - <<'PY'
from semver import VersionInfo

for version in (VersionInfo(1, 2, 3, 'rc.1', 'build.5'), VersionInfo(0)):
    parts = (version.major, version.minor, version.patch, version.prerelease, version.build)
    assert version.to_tuple() == parts
    assert isinstance(version.to_tuple(), tuple)
    expected = dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), parts))
    assert isinstance(version.to_dict(), dict)
    assert version.to_dict() == expected
    result = version.to_dict()
    result['major'] = 99
    assert version.major == parts[0]
    for index in range(-5, 5):
        assert version[index] == parts[index]
    for start in (None, -8, -1, 0, 2, 5, 8):
        for stop in (None, -8, -1, 0, 2, 5, 8):
            for step in (None, -2, -1, 1, 2):
                key = slice(start, stop, step)
                assert version[key] == parts[key]
    for index in (-6, 5):
        try:
            version[index]
        except IndexError:
            pass
        else:
            raise AssertionError('expected IndexError')
    for index in ('major', 1.5, None):
        try:
            version[index]
        except TypeError:
            pass
        else:
            raise AssertionError('expected TypeError')
print('Accessor and indexing checks passed')
PY
